def main():
    with io.open(PATH, "r", encoding="utf-8") as f:
        src = f.read()

    # Find each POI block: id: "X" .... descriptionAdvanced: { de: "..." }
    # Replace single-de descriptionAdvanced with full 4-lang object.
    # Pattern matches: descriptionAdvanced: { de: "..." } where the next non-existent fields will be added.
    # We do per-id replacement.

    total = 0
    skipped_lang = 0

    for poi_id, langs in DATA.items():
        # Find POI block
        # Match: id: "yangon-cities-v2"  ...  descriptionAdvanced: { ... },  factsAdvanced: { de: ... } }
        # We replace just the descriptionAdvanced object value.
        id_pat = re.compile(
            r'(id:\s*"' + re.escape(poi_id) + r'"[\s\S]*?descriptionAdvanced:\s*)\{([^{}]*)\}',
            re.MULTILINE
        )
        m = id_pat.search(src)
        if not m:
            print(f"WARN: POI {poi_id} not found")
            continue

        existing_body = m.group(2)
        # Parse existing langs from body: "de: \"...\"" naively
        existing = {}
        for lang in ("de", "hu", "ro", "en"):
            lm = re.search(r'\b' + lang + r':\s*"((?:\\.|[^"\\])*)"', existing_body)
            if lm:
                existing[lang] = lm.group(1)

        # Build new dict, lang by lang
        out_langs = {}
        for lang in ("de", "hu", "ro", "en"):
            ex = existing.get(lang, "")
            if len(ex) >= 50:
                out_langs[lang] = ex
                if lang in langs:
                    skipped_lang += 1
            else:
                if lang in langs:
                    out_langs[lang] = langs[lang]
                else:
                    out_langs[lang] = ex  # leave as-is (likely empty)

        # Compose new value
        def esc(s): return s.replace("\\", "\\\\").replace('"', '\\"')
        parts = []
        for lang in ("de", "hu", "ro", "en"):
            v = out_langs.get(lang, "")
            parts.append(f'{lang}: "{esc(v)}"')
        new_obj = "{ " + ", ".join(parts) + " }"

        # Replace
        new_src = src[:m.start()] + m.group(1) + new_obj + src[m.end():]
        src = new_src
        total += 1

    with io.open(PATH, "w", encoding="utf-8") as f:
        f.write(src)

    print(f"Updated {total} POIs (4 langs each). Skipped {skipped_lang} already-filled langs.")

if __name__ == "__main__":
    main()
